// Logica de autentificacion

import React, { createContext, useState } from 'react';
import axios from 'axios';

const API_URL = 'http://localhost:3001/api/usuarios'; 

// 1. Crear el contexto
export const AuthContext = createContext();

// Función auxiliar para leer el usuario del localStorage al inicio
const initialState = JSON.parse(localStorage.getItem('user')) || null;

// 2. Crear el Provider
export const AuthProvider = ({ children }) => {
    // currentUser: Almacena los datos del usuario logueado (incluye el id_usuario CRÍTICO)
    const [currentUser, setCurrentUser] = useState(initialState); 

    // --------------------------------------------------------
    // FUNCIÓN DE LOGIN
    // --------------------------------------------------------
    const login = async (correo, contrasena) => {
        try {
            // Petición POST a la ruta de login del backend
            const response = await axios.post(`${API_URL}/login`, {
                correo,
                contrasena
            });

            const user = response.data.user;

            // 🛑 Lógica de roles:
            // Usamos .toLowerCase() para asegurar la compatibilidad con el backend
            if (user.rol.toLowerCase() === 'cliente') {
                // Guarda la sesión
                setCurrentUser(user);
                localStorage.setItem('user', JSON.stringify(user));
                return { success: true }; 
            } 
            else if (user.rol.toLowerCase() === 'administrador') {
                // El admin requiere verificación de código
                return { success: false, needs_code: true }; 
            } 
            else {
                // Si el rol no es cliente ni administrador
                return { success: false, message: "Rol de usuario no reconocido." };
            }

        } catch (error) {
            // Captura errores 401, 404, o de red
            const message = error.response?.data?.message || "Error de conexión o credenciales inválidas.";
            return { success: false, message: message };
        }
    };
    
    // Función para cerrar sesión (necesaria)
    const logout = () => {
        setCurrentUser(null);
        localStorage.removeItem('user');
    };
    // --------------------------------------------------------

    // 3. Devolver el Provider con el contexto
    return (
        <AuthContext.Provider value={{ 
            currentUser, 
            login, 
            logout,
            isLoggedIn: !!currentUser // Útil para verificar si hay sesión
        }}>
            {children}
        </AuthContext.Provider>
    );
};
